import java.util.*;

class Solution {
    private static final int[][] DIRS = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
    private int[][] heights;
    private int m, n;
    private boolean canP, canA;

    public List<List<Integer>> pacificAtlantic(int[][] heights) {
        this.heights = heights;
        this.m = heights.length;
        this.n = heights[0].length;
        List<List<Integer>> result = new ArrayList<>();

        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                boolean[][] visited = new boolean[m][n];
                canP = false;
                canA = false;
                dfs(r, c, visited);
                if (canP && canA) result.add(Arrays.asList(r, c));
            }
        }
        return result;
    }

    private void dfs(int r, int c, boolean[][] visited) {
        if (visited[r][c]) return;
        visited[r][c] = true;
        if (r == 0 || c == 0) canP = true;
        if (r == m - 1 || c == n - 1) canA = true;
        if (canP && canA) return;

        for (int[] d : DIRS) {
            int nr = r + d[0];
            int nc = c + d[1];
            if (nr < 0 || nr >= m || nc < 0 || nc >= n) continue;
            if (heights[nr][nc] > heights[r][c]) continue;
            dfs(nr, nc, visited);
        }
    }
}

import java.util.*;

class Solution {
    private static final int[][] DIRS = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
    private int[][] h;
    private int m, n;

    public List<List<Integer>> pacificAtlantic(int[][] heights) {
        this.h = heights;
        this.m = heights.length;
        this.n = heights[0].length;
        boolean[][] canP = new boolean[m][n];
        boolean[][] canA = new boolean[m][n];

        for (int c = 0; c < n; c++) {
            dfs(0, c, canP);
            dfs(m - 1, c, canA);
        }
        for (int r = 0; r < m; r++) {
            dfs(r, 0, canP);
            dfs(r, n - 1, canA);
        }

        List<List<Integer>> result = new ArrayList<>();
        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                if (canP[r][c] && canA[r][c]) result.add(Arrays.asList(r, c));
            }
        }
        return result;
    }

    private void dfs(int r, int c, boolean[][] can) {
        if (can[r][c]) return;
        can[r][c] = true;
        for (int[] d : DIRS) {
            int nr = r + d[0];
            int nc = c + d[1];
            if (nr < 0 || nr >= m || nc < 0 || nc >= n) continue;
            if (h[nr][nc] < h[r][c]) continue;
            dfs(nr, nc, can);
        }
    }
}

import java.util.*;

class Solution {
    private static final int[][] DIRS = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
    private static final int PACIFIC = 1;
    private static final int ATLANTIC = 2;

    public List<List<Integer>> pacificAtlantic(int[][] heights) {
        int m = heights.length;
        int n = heights[0].length;
        int[][] state = new int[m][n];

        for (int c = 0; c < n; c++) {
            bfs(heights, state, 0, c, PACIFIC, m, n);
            bfs(heights, state, m - 1, c, ATLANTIC, m, n);
        }
        for (int r = 0; r < m; r++) {
            bfs(heights, state, r, 0, PACIFIC, m, n);
            bfs(heights, state, r, n - 1, ATLANTIC, m, n);
        }

        List<List<Integer>> result = new ArrayList<>();
        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                if (state[r][c] == (PACIFIC | ATLANTIC)) result.add(Arrays.asList(r, c));
            }
        }
        return result;
    }

    private void bfs(int[][] h, int[][] state, int sr, int sc, int bit, int m, int n) {
        if ((state[sr][sc] & bit) != 0) return;
        Deque<int[]> queue = new ArrayDeque<>();
        state[sr][sc] |= bit;
        queue.add(new int[]{sr, sc});

        while (!queue.isEmpty()) {
            int[] cur = queue.poll();
            for (int[] d : DIRS) {
                int nr = cur[0] + d[0];
                int nc = cur[1] + d[1];
                if (nr < 0 || nr >= m || nc < 0 || nc >= n) continue;
                if (h[nr][nc] < h[cur[0]][cur[1]]) continue;
                if ((state[nr][nc] & bit) != 0) continue;
                state[nr][nc] |= bit;
                queue.add(new int[]{nr, nc});
            }
        }
    }
}
